-- 0044: the product owner's brain-region table of 2026-11-27.
--
-- What changed against the first table (0018):
--   * movement in intervals may now also come back continuously (type 4) wherever the row lists intervals with a
--     return path: cerebellum, DLPFC, orbitofrontal and pons, both sides;
--   * right orbitofrontal: continuous movement runs LTR and TLDBR (the first table had "LTR, LTR");
--   * new sub-lobes under Subcortical, both sides: basal ganglia – direct pathway and – indirect pathway;
--   * the pons and the mesencephalon are labelled under "Brainstem" (codes and paths unchanged).
-- Every row obeys the eye-movement rule (continuous toward the hemisphere, intervals away): packages/db/test checks it.
--
-- Data only: no table, column or policy changes. A changed row goes back to draft and its revision goes up by one,
-- so sessions keep the revision they actually ran with. Generated by sublobeRevisionSql() and settingRevisionSql();
-- a test checks this file still contains what they generate.

-- ---------------------------------------------------------------- the tree: new sub-lobes, new labels
UPDATE app.brain_region SET labels = jsonb_build_object('en', 'Brainstem – Pons', 'he', 'גזע המוח – גשר (פונס)') WHERE path = 'left.subcortical.pons';
UPDATE app.brain_region SET labels = jsonb_build_object('en', 'Brainstem – Mesencephalon (midbrain)', 'he', 'גזע המוח – המוח התיכון') WHERE path = 'left.subcortical.mesencephalon';
INSERT INTO app.brain_region (kind, code, path, parent_id, labels, sort) SELECT 'sublobe', 'basal_ganglia_direct', 'left.subcortical.basal_ganglia_direct', id, jsonb_build_object('en', 'Basal ganglia – direct pathway', 'he', 'גרעיני הבסיס – המסלול הישיר'), 110 FROM app.brain_region WHERE path = 'left.subcortical';
INSERT INTO app.brain_region (kind, code, path, parent_id, labels, sort) SELECT 'sublobe', 'basal_ganglia_indirect', 'left.subcortical.basal_ganglia_indirect', id, jsonb_build_object('en', 'Basal ganglia – indirect pathway', 'he', 'גרעיני הבסיס – המסלול העקיף'), 111 FROM app.brain_region WHERE path = 'left.subcortical';
UPDATE app.brain_region SET labels = jsonb_build_object('en', 'Brainstem – Pons', 'he', 'גזע המוח – גשר (פונס)') WHERE path = 'right.subcortical.pons';
UPDATE app.brain_region SET labels = jsonb_build_object('en', 'Brainstem – Mesencephalon (midbrain)', 'he', 'גזע המוח – המוח התיכון') WHERE path = 'right.subcortical.mesencephalon';
INSERT INTO app.brain_region (kind, code, path, parent_id, labels, sort) SELECT 'sublobe', 'basal_ganglia_direct', 'right.subcortical.basal_ganglia_direct', id, jsonb_build_object('en', 'Basal ganglia – direct pathway', 'he', 'גרעיני הבסיס – המסלול הישיר'), 110 FROM app.brain_region WHERE path = 'right.subcortical';
INSERT INTO app.brain_region (kind, code, path, parent_id, labels, sort) SELECT 'sublobe', 'basal_ganglia_indirect', 'right.subcortical.basal_ganglia_indirect', id, jsonb_build_object('en', 'Basal ganglia – indirect pathway', 'he', 'גרעיני הבסיס – המסלול העקיף'), 111 FROM app.brain_region WHERE path = 'right.subcortical';

-- ---------------------------------------------------------------- the table: changed rows, new rows
UPDATE app.region_setting s SET bg_temperature = 'cold', bg_types = ARRAY['textured', 'solid']::text[], motion = '[{"movement_types":[0,3],"directions":["tldbr"]},{"movement_types":[1,4],"directions":["brdtl"]}]'::jsonb, target_locations = ARRAY['W', 'SW', 'NW', 'N', 'S']::text[], rotation = 'cw', clinical_status = 'draft', revision = s.revision + 1, updated_at = now() FROM app.brain_region b WHERE b.id = s.sublobe_id AND b.path = 'left.subcortical.cerebellum';
UPDATE app.region_setting s SET bg_temperature = 'cold', bg_types = ARRAY['textured']::text[], motion = '[{"movement_types":[0,3],"directions":["ltr","tldbr"]},{"movement_types":[1,4],"directions":["rtl","brdtl"]}]'::jsonb, target_locations = ARRAY['W', 'SW', 'S']::text[], rotation = 'cw', clinical_status = 'draft', revision = s.revision + 1, updated_at = now() FROM app.brain_region b WHERE b.id = s.sublobe_id AND b.path = 'right.frontal.dlpfc';
